import { describe, it, expect } from "vitest";
import { nextGeneration } from "./game-of-life.js";

describe("Game of Life - Next Generation", () => {
  it.todo("returns an empty grid for an empty grid — [] → []");
  it.todo("kills a single live cell with no neighbors — [(0,0)] → []");
  it.todo(
    "Rule 1 Underpopulation: kills two adjacent cells, each with 1 neighbor — [(0,1), (1,1)] → []",
  );
  it.todo(
    "Rule 2 Survival: a live cell with 3 live neighbors lives on — [(0,0), (1,0), (2,0), (1,2)] → contains (1,1)... wait",
  );
  it.todo(
    "Rule 3 Overpopulation: a live cell with 4 live neighbors dies — center (1,1) is absent from the next generation",
  );
  it.todo(
    "Rule 4 Reproduction: a dead cell with exactly 3 live neighbors becomes alive — [(0,0), (1,0), (0,1)] → includes (1,1)",
  );
  it.todo(
    "Block still life: [(0,0), (1,0), (0,1), (1,1)] stays unchanged",
  );
  it.todo(
    "Blinker gen 0 → gen 1: [(0,0), (0,1), (0,2)] → [(-1,1), (0,1), (1,1)]",
  );
  it.todo(
    "Blinker gen 1 → gen 2: [(-1,1), (0,1), (1,1)] → [(0,0), (0,1), (0,2)]",
  );
  it.todo(
    "handles negative coordinates — block at [(-2,-2), (-1,-2), (-2,-1), (-1,-1)] stays unchanged",
  );
});

