    expect(
      nextGeneration([
        [0, 1],
        [1, 1],
      ]),
    ).toEqual([]);
  });
  it("Rule 2 Survival: a live cell with 2 live neighbors lives on — in [(0,0), (1,0), (2,0), (1,2)] the cell (1,0) survives", () => {
